const visual = {
  prepare: function (input) {
    var texts = [
      '解一元一次方程：5x + 2 = 2x + 8',
      '第一步 移项',
      '5x − 2x = 8 − 2',
      '第二步 合并同类项',
      '3x = 6',
      '第三步 系数化为 1',
      'x = 6 ÷ 3 = 2',
      '1',
      '2',
      '3'
    ];
    return texts.map(function (t) { return { kind: 'text', payload: t }; });
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var margin = 36;
    var gap = 24;
    var cardW = (W - margin * 2 - gap * 2) / 3;
    var titleY = 44;
    var cardY = 92;
    var cardH = H - cardY - 34;
    var formulaFont = Math.max(14, Math.min(22, cardW / 10));
    var stepFont = Math.max(14, Math.min(19, cardW / 12));
    var titleFont = Math.max(18, Math.min(26, W / 36));
    var cardXs = [margin, margin + cardW + gap, margin + (cardW + gap) * 2];
    var paths = [];
    var rootChildren = [];
    function addPath(id, commands, stroke, fill, strokeWidth) {
      paths.push({ id: id, commands: commands });
      rootChildren.push({ type: 'path', pathId: id, stroke: stroke, fill: fill || 'none', strokeWidth: strokeWidth || 2 });
    }
    function addLine(id, x1, y1, x2, y2, color, width) {
      addPath(id, visualSdk.axis({ x0: x1, y0: y1, x1: x2, y1: y2, ticks: 0 }), color, 'none', width);
    }
    function addLabel(x, y, text, fontSize, fill, weight, anchor) {
      rootChildren.push({ type: 'label', x: x, y: y, text: text, fontSize: fontSize, fill: fill, fontWeight: weight || 'normal', textAnchor: anchor || 'middle', anchor: anchor || 'middle', fontFamily: 'sans-serif' });
    }
    for (var i = 0; i < 3; i++) {
      var x = cardXs[i];
      addLine('card' + i + 'top', x, cardY, x + cardW, cardY, '#2b4c7e', 2);
      addLine('card' + i + 'right', x + cardW, cardY, x + cardW, cardY + cardH, '#2b4c7e', 2);
      addLine('card' + i + 'bottom', x + cardW, cardY + cardH, x, cardY + cardH, '#2b4c7e', 2);
      addLine('card' + i + 'left', x, cardY + cardH, x, cardY, '#2b4c7e', 2);
    }
    var arrowY = cardY + cardH / 2;
    addPath('arrow1', visualSdk.arrow(cardXs[0] + cardW + 4, arrowY, cardXs[1] - 4, arrowY, {}), '#2b4c7e', 'none', 2);
    addPath('arrow2', visualSdk.arrow(cardXs[1] + cardW + 4, arrowY, cardXs[2] - 4, arrowY, {}), '#2b4c7e', 'none', 2);
    for (i = 0; i < 3; i++) {
      var cx = cardXs[i] + 24;
      var cy = cardY + 28;
      addPath('stepCircle' + i, visualSdk.circle(cx, cy, 14), '#2b4c7e', '#e8f1fb', 2);
    }
    addLabel(W / 2, titleY, '解一元一次方程：5x + 2 = 2x + 8', titleFont, '#10243e', 'bold', 'middle');
    var stepTitles = ['第一步 移项', '第二步 合并同类项', '第三步 系数化为 1'];
    var formulas = ['5x − 2x = 8 − 2', '3x = 6', 'x = 6 ÷ 3 = 2'];
    var nums = ['1', '2', '3'];
    for (i = 0; i < 3; i++) {
      var x0 = cardXs[i];
      addLabel(x0 + cardW / 2, cardY + 34, stepTitles[i], stepFont, '#10243e', 'bold', 'middle');
      addLabel(x0 + cardW / 2, cardY + cardH / 2 + 10, formulas[i], formulaFont, '#0b3d6e', 'bold', 'middle');
      addLabel(x0 + 24, cardY + 34, nums[i], Math.min(16, stepFont), '#10243e', 'bold', 'middle');
    }
    return { schemaVersion: 1, sceneId: 'equation-flow-card', revision: input.revision, viewBox: { x: 0, y: 0, width: W, height: H }, paths: paths, root: { type: 'group', children: rootChildren } };
  }
};
